#include "MeshBooleanBroadPhaseFixtures.h"
#include <iostream>
using namespace broad_test;
template<class T,class I>void stage_cases(){for(auto boxes:std::vector<std::pair<std::pair<T,T>,std::pair<T,T>>>{{{T(0),T(1)},{T(1),T(2)}},{{T(0),T(1)},{T(2),T(3)}}}){auto a=box<T,I>(boxes.first.first,boxes.first.second),b=box<T,I>(boxes.second.first,boxes.second.second);auto r=broad_test::registry();auto c=context(a,b,r);auto result=enumerate_broad_phase_candidates(*c);require(result.has_value(),"stage succeeds");const auto&stream=*result.value()->payload;auto expected=exhaustive(*stream.validated->payload);require(stream.candidates.size()==expected.size(),"exhaustive equality");require(result.value()->report.passed(),"verified");for(std::size_t i=0;i<expected.size();++i){require(stream.candidates[i].id.value_for_debug()==i,"dense IDs");require(stream.candidates[i].key==expected[i],"canonical key");}}}
void bounds(){exact_scalar z(0),o(1),t(2);exact_feature_bound3 a{{z,o,true,true},{z,o,true,true},{z,o,true,true}},touch{{o,t,true,true},{z,o,true,true},{z,o,true,true}},gap{{t,t,true,true},{z,o,true,true},{z,o,true,true}};require(valid_exact_feature_bound(a),"valid bound");require(exact_bounds_overlap(a,touch),"touch overlaps");require(!exact_bounds_overlap(a,gap),"strict gap");auto u=exact_bound_union(a,gap);require(u.x.lower==z&&u.x.upper==t,"union");}
void self_query(){auto owner=make_context_owner_token();exact_scalar z(0),o(1),t(2);auto b=[&](exact_scalar lo,exact_scalar hi){return exact_feature_bound3{{lo,hi,true,true},{z,o,true,true},{z,o,true,true}};};std::vector<bounded_feature_view>v={{{owner,7,0},bound_source_kind::exact_box,b(z,o),bound_fallback_reason::caller_requested},{{owner,7,1},bound_source_kind::exact_box,b(o,t),bound_fallback_reason::caller_requested},{{owner,7,2},bound_source_kind::exhaustive_fallback,{},bound_fallback_reason::missing_exact_bound}};auto q=enumerate_bounded_feature_self(v);require(q.has_value()&&q.value().size()==3,"self touching and fallback");}
int main(){try{bounds();self_query();stage_cases<float,std::uint32_t>();stage_cases<float,std::uint64_t>();stage_cases<double,std::uint32_t>();stage_cases<double,std::uint64_t>();std::cout<<"PASS broad phase unit\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
